#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

#define PTE_PRESENT 0x01
#define PTE_RW      0x02
#define PTE_USER    0x04
#define PTE_ACCESSED 0x20
#define PTE_DIRTY   0x40

#define ACCESS_USER  0x04
#define ACCESS_WRITE 0x02

typedef struct {
    uint32_t gva_tag;
    uint32_t hpa_val;
    uint32_t access_flags;
    bool valid;
} tlb_entry_t;

typedef struct {
    uint8_t *phys_memory;
    uint32_t guest_cr3;
    uint32_t reserved;
    tlb_entry_t tlb_entries[16];
    uint32_t tlb_rr_index;
} mmu_ctx_t;

bool mmu_translate_gva(mmu_ctx_t *ctx, uint32_t gva, uint32_t access_flags, uint32_t *out_hpa, uint32_t *out_fault_error) {
    uint32_t tag = gva & ~0xFFF;

    // 1. TLB Lookup
    for (int i = 0; i < 16; i++) {
        if (ctx->tlb_entries[i].valid && ctx->tlb_entries[i].gva_tag == tag) {
            // TLB hit. Check permissions
            bool user_allowed = (ctx->tlb_entries[i].access_flags & ACCESS_USER) || !(access_flags & ACCESS_USER);
            bool write_allowed = (ctx->tlb_entries[i].access_flags & ACCESS_WRITE) || !(access_flags & ACCESS_WRITE);
            if (user_allowed && write_allowed) {
                *out_hpa = ctx->tlb_entries[i].hpa_val + (gva & 0xFFF);
                return true;
            }
        }
    }

    // 2. Page Table Walk (3-level)
    // Level 1: PDPT (bits 31-22)
    uint32_t pdpt_idx = (gva >> 22) & 0x3FF;
    // Level 2: PD (bits 21-12)
    uint32_t pd_idx = (gva >> 12) & 0x3FF;
    // Level 3: PT (bits 11-2)
    uint32_t pt_idx = (gva >> 2) & 0x3FF;

    uint32_t pte_addr = ctx->guest_cr3 + pdpt_idx * 4;
    uint32_t pte = *(uint32_t*)(ctx->phys_memory + pte_addr);

    if (!(pte & PTE_PRESENT)) { *out_fault_error = 0; return false; }
    if ((access_flags & ACCESS_USER) && !(pte & PTE_USER)) { *out_fault_error = 0; return false; }
    if ((access_flags & ACCESS_WRITE) && !(pte & PTE_RW)) { *out_fault_error = 0; return false; }

    pte_addr = (pte & ~0xFFF) + pd_idx * 4;
    pte = *(uint32_t*)(ctx->phys_memory + pte_addr);

    if (!(pte & PTE_PRESENT)) { *out_fault_error = 0; return false; }
    if ((access_flags & ACCESS_USER) && !(pte & PTE_USER)) { *out_fault_error = 0; return false; }
    if ((access_flags & ACCESS_WRITE) && !(pte & PTE_RW)) { *out_fault_error = 0; return false; }

    pte_addr = (pte & ~0xFFF) + pt_idx * 4;
    pte = *(uint32_t*)(ctx->phys_memory + pte_addr);

    if (!(pte & PTE_PRESENT)) { *out_fault_error = 0; return false; }
    if ((access_flags & ACCESS_USER) && !(pte & PTE_USER)) { *out_fault_error = 0; return false; }
    if ((access_flags & ACCESS_WRITE) && !(pte & PTE_RW)) { *out_fault_error = 0; return false; }

    // Update PTE flags
    pte |= PTE_ACCESSED;
    if (access_flags & ACCESS_WRITE) pte |= PTE_DIRTY;
    *(uint32_t*)(ctx->phys_memory + pte_addr) = pte;

    uint32_t hpa_base = pte & ~0xFFF;
    *out_hpa = hpa_base + (gva & 0xFFF);

    // Populate TLB
    uint32_t rr = ctx->tlb_rr_index % 16;
    ctx->tlb_entries[rr].valid = true;
    ctx->tlb_entries[rr].gva_tag = tag;
    ctx->tlb_entries[rr].hpa_val = hpa_base;

    // Derive TLB max permissions from walk (simplified: we just store the access_flags that succeeded, or full permissions?)
    // The prompt says "Cache the translation into Software TLB"
    // Let's cache the PTE permissions:
    uint32_t cached_flags = 0;
    if (pte & PTE_USER) cached_flags |= ACCESS_USER;
    if (pte & PTE_RW)   cached_flags |= ACCESS_WRITE;
    ctx->tlb_entries[rr].access_flags = cached_flags;

    ctx->tlb_rr_index = (rr + 1) % 16;

    return true;
}

void mmu_tlb_flush(mmu_ctx_t *ctx) {
    for (int i = 0; i < 16; i++) ctx->tlb_entries[i].valid = false;
}

void mmu_invlpg(mmu_ctx_t *ctx, uint32_t gva) {
    uint32_t tag = gva & ~0xFFF;
    for (int i = 0; i < 16; i++) {
        if (ctx->tlb_entries[i].valid && ctx->tlb_entries[i].gva_tag == tag) {
            ctx->tlb_entries[i].valid = false;
        }
    }
}
